-- 瑠璃急行線（系統30）のダイヤを組みなおす（2026-10-30。ローカルの写しで組んで、重なり・走れない列車が0になるのを確かめたもの）
--   特急（毎時1本・見晴温泉口〜瑠璃急翠浜）・快速（30分おき・那国高野台〜瑠璃急翠浜）・普通・普通(牧)。停車駅は本人のパターンのまま
--   中心部（麦畑北楓〜夕凪高砂）は、普通が10分おき。普通は決まった駅で少し長く止まり、そこで快速・特急が追いこす
--   本数：快速 62本（編成10）・普通 477本（編成29）・普通(牧) 64本（編成6）・特急 31本（編成5）。運用は種別ごと（運用番号は編成の名前のまま）
--   瑠璃快速•開臨若葉直通線（系統13）：柏木栄・美東中央の番線を走る向きにあわせ（50本）、重なる22本を少しずらす。玖珠線（系統8）：富士見瑠璃越は3・4番線（62本）
--   前のダイヤは、それぞれの系統の「↶ 取り消す」1回でもどせます
--   前提（駅・区間・停車駅のパターン・番線・系統8と13の列車・編成）が変わっていたら、何も変えずに止まります
--   （2026-10-31 なおし：前提がちがう・注意が出るときは、このダイヤだけ前のままにして、更新はつづける。わけは WARNING に出る）
-- 区間をくらべる（長さ・位置の小数のずれ 0.5m までは同じと見る）。この更新のあいだだけの関数
create function pg_temp.kz_leg_diff(a jsonb, b jsonb) returns text language sql immutable as $f$
  select nullif(concat_ws(',',
    case when (a ->> 'e') is distinct from (b ->> 'e') then '電化' end,
    case when (a ->> 's') is distinct from (b ->> 's') then '単線' end,
    case when abs(coalesce((a ->> 'd')::numeric, -9) - coalesce((b ->> 'd')::numeric, -9)) > 0.5
         then format('長さ %sm→%sm', round((b ->> 'd')::numeric), round((a ->> 'd')::numeric)) end,
    case when (a -> 'p') is distinct from (b -> 'p') then '速さ' end,
    case when jsonb_array_length(coalesce(a -> 'g', '[]')) <> jsonb_array_length(coalesce(b -> 'g', '[]'))
           or exists (select 1 from jsonb_array_elements(coalesce(a -> 'g', '[]')) with ordinality x(v, o)
                        join jsonb_array_elements(coalesce(b -> 'g', '[]')) with ordinality y(w, o2) on o2 = o
                       where (v ->> 0) is distinct from (w ->> 0) or abs((v ->> 1)::numeric - (w ->> 1)::numeric) > 0.5
                          or abs((v ->> 2)::numeric - (w ->> 2)::numeric) > 0.5) then '線路' end,
    case when (select array_agg(k order by k) from jsonb_object_keys(a) k) is distinct from (select array_agg(k order by k) from jsonb_object_keys(b) k) then '項目' end), '')
$f$;
