3d58874033b302e9245fe4f014e239","632":"c5e8929f45d1e18dfed3d8d6404b7def","633":"88e23e0c25fca7dc263d433a484cf9d7","634":"91bee9c2e63834277fdd02e4ed451843","635":"8e1422c0d8f2b386240d2c60ce2b4810","636":"8ace7b72f5a001e0c842a3da7294cdf5","637":"4266e090d097671f2fab70f7ea2c8cf9","638":"c453de9398b0f888896bf5515690c20c","639":"f72a9307f2d66ea6efe6a2c8969a5dee","640":"13bb446c2b44c047dc3ad3494cdda0f0","641":"411be5fcf2231d4ea3e659734f5c823c","642":"c82195345d0d0bf9c664d2d0b4a46171","643":"af8541c8ff21885b2151ccd84a00bf7c","644":"0d1a2bccc3cadbbb9a898cfd1ec808b3","645":"3803444e06bdc42a08dce4a322f9b373","646":"ac326a3bd0b33859780e9530ba859e75","647":"bff2e533db90d31a1790ac6b6bd704f9","648":"f80f82c8dd8c65fd87e8f9617e618dd5","649":"ec766faa6df8315d7a693b49e3cb3266","650":"18aebff62d654ffc175b1e3a34cd21e0","651":"c922268d40ec10a7135c77c14fdc4f44","652":"1bde6742707a956775e2d5bc6d422255","653":"bb92cddcdf57753b2ad587ee90279b6f","654":"b1e3a08d5137758619ab8e95bf2a1df1"}}$e$::jsonb; nm text[] := array['U11','U12','U13','U14','U15','U16','U17','U18','U19','U20','U21','U22','U23','U24','U25','U26','U27','U28','U29','U30','U31','U32','U33','U34','U35','U36','U37','U38','U39','U49','U50','U51','U52','U53','U54','U55','U56','U57','U58','U65','U66','U67','U68','U69','X02','X03','X04','X05','X06','X07']::text[];
        bad text[] := '{}'; n int; n2 int; s text; rid int; nbad int; w text; stn text;
begin
 begin   -- ここから下で止まったら、このダイヤの変更だけを取り消して、更新はつづける
  select * into r from mp_routes where id = 30;
  if not found then raise exception '瑠璃急行線（系統30）が見つかりません'; end if;
  -- 前提（写しと同じか）。ちがうところをぜんぶ書いて止まる
  if r.kind is distinct from e #>> '{r,kind}' then bad := bad || format('系統30の種類（%s）', r.kind); end if;
  if r.dwell is distinct from (e #>> '{r,dwell}')::int then bad := bad || format('停車時間（いま%s秒・前は%s秒）', r.dwell, e #>> '{r,dwell}'); end if;
  if r.stops is distinct from array(select v::bigint from jsonb_array_elements_text(e #> '{r,stops}') with ordinality z(v, o) order by o) then
    bad := bad || format('駅の並び（いま%s駅・前は%s駅。いま %s）', cardinality(r.stops), jsonb_array_length(e #> '{r,stops}'), r.stops::text);
  end if;
  if r.pats is distinct from e #> '{r,pats}' then
    bad := bad || format('停車駅のパターン（%s。いま %s）', coalesce((select string_agg(k, '・') from (select jsonb_object_keys(coalesce(r.pats, '{}'::jsonb)) k
                                                    union select jsonb_object_keys(e #> '{r,pats}')) z where (r.pats -> k) is distinct from (e #> '{r,pats}' -> k)), '?'), r.pats::text);
  end if;
  if jsonb_array_length(coalesce(r.legs, '[]')) <> jsonb_array_length(e #> '{r,legs}') then
    bad := bad || format('区間の数（いま%s・前は%s）', jsonb_array_length(coalesce(r.legs, '[]')), jsonb_array_length(e #> '{r,legs}'));
  else
    select count(*), string_agg(format('%s〜%s：%s', a1, a2, df), '／' order by o) filter (where k <= 4) into n, s from (
      select z.*, row_number() over (order by o) k from (
        select x.o, (select name from mp_stations where id = r.stops[x.o]) a1, (select name from mp_stations where id = r.stops[x.o + 1]) a2,
               pg_temp.kz_leg_diff(x.l, e #> array['r', 'legs', (x.o - 1)::text]) df
          from jsonb_array_elements(r.legs) with ordinality x(l, o)) z where z.df is not null) q;
    if n > 0 then bad := bad || format('区間 %s か所（%s）', n, s); end if;
  end if;
  select count(*), string_agg(coalesce(st.name, '（消えた駅 ' || (x.v ->> 'id') || '）'), '・') into n, s
    from jsonb_array_elements(e -> 'st') x(v) left join mp_stations st on st.id = (x.v ->> 'id')::bigint
   where st.id is null or st.tracks is distinct from (x.v ->> 'tracks')::int or st.plat is distinct from (x.v ->> 'plat')::int
      or _mp_sta_trk(st)::text is distinct from (x.v ->> 'trk');
  -- 駅の番線・ホームのちがいでは止めない（ダイヤの中で番線を決めていない駅がほとんど）。あとのたしかめで注意が出たら、いっしょに書く
  if n > 0 then stn := format('駅の番線・ホームが写しとちがう %s駅（%s）', n, left(s, 200)); raise warning '%（ダイヤはそのまま入れて、注意が出ないかたしかめます）', stn; end if;
  foreach rid in array array[13, 8] loop
    select count(*), string_agg(coalesce(t.num, '（消えた列車 ' || z.id || '）'), '・') into n, s
      from jsonb_each_text(e -> ('t' || rid)) z(id, h) left join mp_trains t on t.id = z.id::bigint and t.route = rid
     where t.id is null or md5(concat_ws(':', t.dir, t.num, t.kind, t.dep, t.tt::text, t.skip::text, t.sa, t.sb, t.form, t.day, t.cpl::text)) <> z.h;
    select count(*) into n2 from mp_trains t where t.route = rid and not ((e -> ('t' || rid)) ? t.id::text);
    if n > 0 or n2 > 0 then bad := bad || format('系統%s の列車 %s本がちがう・%s本ふえた（%s）', rid, n, n2, left(coalesce(s, ''), 200)); end if;
  end loop;
  select string_agg(x, '・') into s from unnest(nm) x where not exists (select 1 from mp_forms f where f.own_u = r.own_u and f.own_c is null and f.name = x);
  if s is not null then bad := bad || format('編成が見つからない（%s）', s); end if;
  select string_agg(z.name, '・') into s from (select f.name from mp_forms f where f.own_u = r.own_u and f.own_c is null and f.name = any(nm) group by 1 having count(*) > 1) z;
  if s is not null then bad := bad || format('同じ名前の編成が2つ（%s）', s); end if;
  select string_agg(distinct f.name || '→系統' || t.route, '・') into s from mp_trains t join mp_forms f on f.id = t.form
   where t.route <> 30 and f.own_u = r.own_u and f.own_c is null and f.name = any(nm);
  if s is not null then bad := bad || format('ほかの系統で使っている編成（%s）', left(s, 200)); end if;
  if cardinality(bad) > 0 then raise exception '前提がちがうので、何も変えずに止めます：%', array_to_string(bad, ' ／ '); end if;
  -- 「↶ 取り消す」でもどせるように、前のダイヤをのこす
  perform _mp_dia_snap(30, '更新：ダイヤを組みなおした（特急・快速・普通）');
  perform _mp_dia_snap(13, '更新：瑠璃急行線にあわせて時刻をずらした');
  perform _mp_dia_snap(8, '更新：富士見瑠璃越は3・4番線');
  delete from mp_trains where route = 30;
